 1	public final class LongestCommonSubsequenceTest {
 2	    private LongestCommonSubsequenceTest() {
 3	    }
 4	
 5	    public static void main(String[] args) {
 6	        assertLcs("AGGTAB", "GXTXAYB", 4);
 7	        assertLcs("", "abc", 0);
 8	        assertLcs("abc", "", 0);
 9	        assertLcs("abc", "abc", 3);
10	        assertLcs("abc", "def", 0);
11	        assertLcs("ABCDGH", "AEDFHR", 3);
12	        assertLcs("XMJYAUZ", "MZJAWXU", 4);
13	        assertSymmetric("abcde", "ace");
14	        assertNullRejected();
15	
16	        System.out.println("All tests passed.");
17	    }
