19	    private static void assertLcs(String first, String second, int expected) {
20	        int actual = LongestCommonSubsequence.lcs(first, second);
21	
22	        if (actual != expected) {
23	            throw new AssertionError(
24	                "Expected LCS length %d for \"%s\" and \"%s\" but got %d"
25	                    .formatted(expected, first, second, actual)
26	            );
27	        }
28	    }
29	
30	    private static void assertSymmetric(String first, String second) {
31	        int forward = LongestCommonSubsequence.lcs(first, second);
32	        int reverse = LongestCommonSubsequence.lcs(second, first);
33	
34	        if (forward != reverse) {
35	            throw new AssertionError(
36	                "Expected symmetry for \"%s\" and \"%s\" but got %d and %d"
37	                    .formatted(first, second, forward, reverse)
38	            );
39	        }
40	    }
41	
42	    private static void assertNullRejected() {
43	        assertNullRejected(null, "abc", "first must not be null");
44	        assertNullRejected("abc", null, "second must not be null");
45	    }
