47	    private static void assertNullRejected(String first, String second, String message) {
48	        try {
49	            LongestCommonSubsequence.lcs(first, second);
50	            throw new AssertionError("Expected NullPointerException");
51	        } catch (NullPointerException exception) {
52	            if (!message.equals(exception.getMessage())) {
53	                throw new AssertionError(
54	                    "Expected message \"%s\" but got \"%s\""
55	                        .formatted(message, exception.getMessage())
